import React, { useState } from 'react';
import Dashboard from './components/Dashboard';
import AppointmentFlow from './components/AppointmentFlow';
import TransportStatus from './components/TransportStatus';

// Mock data for the flow demonstration
const mockAppointmentData = {
    date: 'Dec 10',
    time: '10:00 AM',
    hasTransportBooked: false,
};

function App() {
    const [page, setPage] = useState('dashboard'); // 'dashboard', 'appointment', 'transport'
    const [isEasyMode, setIsEasyMode] = useState(true); // Start in Easy Mode for the demo

    // A mock function for the pop-up/redirect
    const handleNotificationClick = () => {
        setPage('appointment');
    };

    const renderPage = () => {
        if (page === 'appointment') {
            return (
                <AppointmentFlow
                    isEasyMode={isEasyMode}
                    appointment={mockAppointmentData}
                    goToTransportStatus={() => setPage('transport')}
                />
            );
        }
        if (page === 'transport') {
            return (
                <TransportStatus
                    isEasyMode={isEasyMode}
                    goToDashboard={() => setPage('dashboard')}
                />
            );
        }
        // Default is Dashboard
        return (
            <Dashboard
                isEasyMode={isEasyMode}
                goToMedical={() => setPage('appointment')} // For the hackathon, clicking Medical goes straight to the flow
            />
        );
    };

    return (
        <div className={`App ${isEasyMode ? 'easy-mode-theme' : 'standard-theme'}`}>
            <h1>Accessible App Demo</h1>
            <button onClick={() => setIsEasyMode(!isEasyMode)}>
                {isEasyMode ? 'Switch to Standard Mode' : 'Switch to Easy Mode'}
            </button>
            <hr />

            {/* Mock 3-Day Notification Banner */}
            {page === 'dashboard' && (
                <div 
                    onClick={handleNotificationClick}
                    style={{ 
                        padding: '10px', 
                        margin: '20px', 
                        backgroundColor: 'lightcoral', 
                        cursor: 'pointer',
                        fontSize: isEasyMode ? '24px' : '16px'
                    }}
                >
                    🚨 **NOTIFICATION: Appointment Soon! Tap Here!**
                </div>
            )}
            
            {renderPage()}
        </div>
    );
}

export default App;
